-- ADR-0119: interruption rows. ADDITIVE and deliberately NOT a table rebuild: session_messages carries the ADR-0104
-- coverage triggers and its b-tree root page is pinned by the upgrade tests, and a rebuild drops the former and moves
-- the latter. drizzle-kit would generate a rebuild for table-level CHECKs, so the same three constraints are written
-- as column constraints, which SQLite accepts on ADD COLUMN and tests against existing rows (all NULL, so they hold).
-- A fresh database and an upgraded one both come from this file, so they carry identical constraints.
ALTER TABLE `session_messages` ADD `interruption_reason` text CONSTRAINT "session_messages_interruption_reason_check" CHECK ("interruption_reason" is null or "interruption_reason" in ('aborted', 'failed', 'denied', 'turn_limit'));--> statement-breakpoint
ALTER TABLE `session_messages` ADD `interruption_code` text CONSTRAINT "session_messages_interruption_code_check" CHECK ("interruption_code" is null or "interruption_code" in ('validation', 'context_overflow', 'content_filter', 'provider_auth', 'provider_rate_limit', 'provider_unavailable', 'tool_denied', 'tool_failed', 'tool_unavailable', 'budget_exceeded', 'effect_needs_attention', 'run_timeout', 'turn_limit', 'cancelled', 'sandbox_error', 'internal')) CONSTRAINT "session_messages_interruption_shape_check" CHECK (("interruption_reason" is null and "interruption_code" is null) or ("interruption_reason" is not null and "role" = 'system' and "compaction_dropped_through_sequence" is null and (("interruption_reason" = 'failed') = ("interruption_code" is not null))));
